import java.util.*;

public class Ex03AutoConfigTopoSort {
    static List<String> topoSort(Map<String, List<String>> deps) {
        Map<String, Integer> indeg = new LinkedHashMap<>();
        Map<String, List<String>> adj = new LinkedHashMap<>();
        for (String k : deps.keySet()) { indeg.putIfAbsent(k, 0); adj.putIfAbsent(k, new ArrayList<>()); }
        for (Map.Entry<String, List<String>> e : deps.entrySet()) {
            for (String d : e.getValue()) {          // k 依赖 d : d -> k
                indeg.putIfAbsent(d, 0);
                adj.putIfAbsent(d, new ArrayList<>());
                adj.get(d).add(e.getKey());
                indeg.merge(e.getKey(), 1, Integer::sum);
            }
        }
        // 同层用类名字典序，保证输出确定（Spring 的兜底也是字典序）
        PriorityQueue<String> pq = new PriorityQueue<>();
        for (Map.Entry<String, Integer> e : indeg.entrySet()) if (e.getValue() == 0) pq.add(e.getKey());
        List<String> order = new ArrayList<>();
        while (!pq.isEmpty()) {
            String cur = pq.poll();
            order.add(cur);
            for (String nx : adj.get(cur)) {
                if (indeg.merge(nx, -1, Integer::sum) == 0) pq.add(nx);
            }
        }
        return order;
    }

    public static void main(String[] args) {
        Map<String, List<String>> deps = new LinkedHashMap<>();
        deps.put("MyBatisAutoConfiguration",       List.of("DataSourceAutoConfiguration"));
        deps.put("TransactionAutoConfiguration",   List.of("DataSourceAutoConfiguration"));
        deps.put("DataSourceAutoConfiguration",    List.of());

        List<String> order = topoSort(deps);
        System.out.println("evaluation order (topological):");
        for (int i = 0; i < order.size(); i++) System.out.println("  " + (i + 1) + ". " + order.get(i));
        System.out.println("is DAG = " + (order.size() == deps.size()));

        Map<String, List<String>> cyclic = new LinkedHashMap<>(deps);
        cyclic.put("DataSourceAutoConfiguration", List.of("TransactionAutoConfiguration"));
        List<String> cyc = topoSort(cyclic);
        System.out.println("--- with a cycle ---");
        System.out.println("is DAG = " + (cyc.size() == cyclic.size()));
        System.out.println("resolved order = " + cyc);
    }
}
